```ts
/**
 * A classified failure, plus who is holding the next move.
 *
 * `kind` is the three-way split; `waitingOn` is who is blocking it:
 * `candidate` when there's a login or answer to hand over, `us` when the
 * fix is on our side (wall, bug, unclassified), `nobody` when there is
 * no move at all (posting is gone).
 */
export interface FailurePresentation {
  kind: UserFacingFailure;
  /** `candidate` when actionable, `us` when pending, `nobody` when closed. */
  waitingOn: "candidate" | "nobody" | "us";
}

/** Classify a failure into a presentation. */
export function userFacingFailure(outcome: FailureOutcome): FailurePresentation {
  switch (outcome) {
    case "needs_login":
    case "needs_answer":
      return { kind: "actionable", waitingOn: "candidate" };
    case "posting_gone":
      return { kind: "closed", waitingOn: "nobody" };
    case "wall":
    case "our_bug":
    case "unknown":
      return { kind: "pending", waitingOn: "us" };
  }
}
